  color: var(--text-primary); font-size: 0.875rem; padding: 6px 14px;
  border-radius: var(--radius-sm); cursor: pointer; font-family: inherit;
}

.btn { display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2); font-family: inherit; font-weight: 600; border: none; cursor: pointer; transition: all 0.2s ease; text-decoration: none; white-space: nowrap; }
.btn-primary { background: var(--accent); color: #fff; padding: 10px 24px; border-radius: var(--radius-sm); font-size: 0.9375rem; }
.btn-primary:hover { background: var(--accent-hover); }
.btn-primary-lg { padding: 16px 32px; font-size: 1.25rem; border-radius: var(--radius-md); font-weight: 700; }
.btn-primary-xl { padding: 18px 36px; font-size: 1.375rem; border-radius: var(--radius-md); font-weight: 700; }

/* ── HERO ───────────────────────────── */
.hero {
  position: relative; min-height: 100vh; display: flex; align-items: center;
  overflow: hidden; padding-top: 80px;
}
.hero-bg {
