              radial-gradient(ellipse at 70% 60%, rgba(120,20,200,0.08) 0%, transparent 60%),
              radial-gradient(ellipse at 50% 80%, rgba(30,60,180,0.1) 0%, transparent 50%),
              var(--bg-primary);
