/* Mosaic poster tiles */
.hero-mosaic { position: absolute; inset: -40px; z-index: 1; overflow: hidden; }
.hero-tile {
  position: absolute; width: 160px; height: 220px; border-radius: 8px;
  opacity: 0.18; filter: brightness(0.7);
  background-size: cover; background-position: center;
}
.hero-tile:nth-child(1) { top: 8%; left: 3%; transform: rotate(-8deg); background: linear-gradient(135deg, #1a1a2e, #e94560, #0f3460); }
.hero-tile:nth-child(2) { top: 5%; left: 18%; transform: rotate(5deg); background: linear-gradient(135deg, #2d1b4e, #c84b31, #2d1b4e); }
