.hero-overlay {
  position: absolute; inset: 0; z-index: 2;
  background: linear-gradient(180deg, rgba(10,10,10,0.3) 0%, rgba(10,10,10,0.5) 30%, rgba(10,10,10,0.85) 70%, var(--bg-primary) 100%);
