.hero-content { position: relative; z-index: 3; max-width: 700px; padding: var(--space-8) 0; }
.hero-content h1 { font-family: 'Bebas Neue', 'Inter', sans-serif; font-size: clamp(2.5rem, 6vw, 5rem); font-weight: 400; line-height: 1.05; letter-spacing: -0.01em; margin-bottom: var(--space-3); }
.hero-content .subtitle { font-size: clamp(1.125rem, 2vw, 1.5rem); font-weight: 500; margin-bottom: var(--space-4); color: var(--text-primary); }
.hero-content .prompt { font-size: 1.0625rem; color: var(--text-secondary); margin-bottom: var(--space-3); }

.email-form { display: flex; gap: var(--space-2); max-width: 540px; }
.email-form input {
  flex: 1; padding: 16px 20px; font-size: 1rem; font-family: inherit;
  background: rgba(255,255,255,0.06); border: 1px solid var(--border);
  border-radius: var(--radius-md); color: var(--text-primary);
  outline: none; transition: border-color 0.2s;
}
.email-form input::placeholder { color: var(--text-muted); }
.email-form input:focus { border-color: var(--accent); }

/* ── SECTIONS ───────────────────────── */
.section { padding: var(--space-8) 0; }
.section-header { margin-bottom: var(--space-5); }
.section-header h2 { font-family: 'Bebas Neue', 'Inter', sans-serif; font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 400; letter-spacing: 0.02em; }

.divider { border: none; border-top: 1px solid var(--border); margin: 0; }

/* ── TRENDING CAROUSEL ──────────────── */
.carousel-wrapper { position: relative; }
.carousel {
  display: flex; gap: var(--space-3); overflow-x: auto; scroll-behavior: smooth;
  scroll-snap-type: x mandatory; -webkit-overflow-scrolling: touch;
  padding-bottom: var(--space-3); scrollbar-width: none;
}
.carousel::-webkit-scrollbar { display: none; }

.trending-card {
  flex: 0 0 auto; width: 200px; scroll-snap-align: start;
  position: relative; cursor: pointer; user-select: none;
  transition: transform 0.3s ease;
}
.trending-card:hover { transform: scale(1.05); }

.trending-rank {
  position: absolute; bottom: -8px; left: -12px; z-index: 2;
  font-family: 'Bebas Neue', sans-serif; font-size: clamp(5rem, 8vw, 8rem);
  font-weight: 400; line-height: 0.8; letter-spacing: -0.04em;
  color: transparent; -webkit-text-stroke: 2px rgba(255,255,255,0.3);
  pointer-events: none;
}

.trending-poster {
  width: 200px; height: 280px; border-radius: var(--radius-md);
  position: relative; overflow: hidden;
}
.trending-poster::after {
  content: attr(data-title); position: absolute; bottom: 0; left: 0; right: 0;
  padding: var(--space-5) var(--space-3) var(--space-3);
  background: linear-gradient(transparent, rgba(0,0,0,0.85));
  font-size: 0.875rem; font-weight: 600; color: var(--text-primary);
}

.carousel-arrow {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 5;
  width: 48px; height: 48px; border-radius: 50%; display: flex;
  align-items: center; justify-content: center; border: none; cursor: pointer;
  background: rgba(30,30,30,0.9); color: var(--text-primary); font-size: 1.5rem;
  transition: background 0.2s ease;
}
.carousel-arrow:hover { background: rgba(60,60,60,0.9); }
.carousel-arrow--prev { left: -4px; }
.carousel-arrow--right { right: -4px; }

/* ── FEATURES ───────────────────────── */
.features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: var(--space-4); }
.feature-card {
  background: linear-gradient(145deg, var(--bg-elevated), var(--bg-surface));
  border: 1px solid var(--border); border-radius: var(--radius-lg);
  padding: var(--space-5); position: relative; overflow: hidden;
  transition: transform 0.2s ease, border-color 0.2s ease;
}
.feature-card:hover { transform: translateY(-4px); border-color: var(--border-light); }
.feature-card h3 { font-size: 1.25rem; font-weight: 700; margin-bottom: var(--space-2); }
.feature-card p { color: var(--text-secondary); font-size: 0.9375rem; line-height: 1.55; }
.feature-icon {
