  background: rgba(229,9,20,0.12); margin-top: var(--space-5);
  margin-left: auto;
}
.feature-icon svg { width: 24px; height: 24px; fill: var(--accent); }

/* ── FAQ ────────────────────────────── */
.faq-list { max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; gap: var(--space-2); }
.faq-item { border: 1px solid var(--border); border-radius: var(--radius-md); overflow: hidden; background: var(--bg-surface); }
.faq-question {
  width: 100%; text-align: left; padding: var(--space-4);
  font-family: inherit; font-size: 1.125rem; font-weight: 500;
  color: var(--text-primary); background: none; border: none; cursor: pointer;
  display: flex; justify-content: space-between; align-items: center; gap: var(--space-4);
  transition: background 0.2s ease;
}
.faq-question:hover { background: var(--bg-elevated); }
.faq-icon {
  flex-shrink: 0; width: 32px; height: 32px; position: relative;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.faq-icon::before, .faq-icon::after {
  content: ''; position: absolute; background: var(--text-primary); border-radius: 1px;
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.faq-icon::before { top: 15px; left: 4px; width: 24px; height: 2px; }
.faq-icon::after { top: 4px; left: 15px; width: 2px; height: 24px; }
.faq-item.open .faq-icon { transform: rotate(45deg); }
.faq-answer-wrapper {
  display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.faq-item.open .faq-answer-wrapper { grid-template-rows: 1fr; }
.faq-answer-inner { overflow: hidden; }
.faq-answer {
  padding: 0 var(--space-4) var(--space-4); color: var(--text-secondary);
  font-size: 1rem; line-height: 1.65;
}

/* ── CTA SECTION ────────────────────── */
.cta-section { padding: var(--space-8) 0; text-align: center; }
.cta-section .prompt { font-size: 1.0625rem; color: var(--text-secondary); margin-bottom: var(--space-3); }
.cta-section .email-form { margin: 0 auto; }

/* ── FOOTER ─────────────────────────── */
.footer { padding: var(--space-7) 0 var(--space-5); color: var(--text-muted); font-size: 0.875rem; }
.footer .contact { margin-bottom: var(--space-5); font-size: 0.9375rem; }
.footer .contact a { color: var(--text-muted); }
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: var(--space-3); margin-bottom: var(--space-5); }
.footer-col { display: flex; flex-direction: column; gap: var(--space-2); }
.footer-col a { color: var(--text-muted); text-decoration: underline; text-underline-offset: 3px; transition: color 0.2s; }
.footer-col a:hover { color: var(--text-secondary); }
.footer-bottom { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: var(--space-4); padding-top: var(--space-4); }
.footer-bottom .lang-select { font-size: 0.8125rem; }
.footer-legal { color: var(--text-muted); font-size: 0.8125rem; }

/* ── RESPONSIVE ─────────────────────── */
@media (max-width: 768px) {
  .email-form { flex-direction: column; }
  .header-actions .lang-select { display: none; }
  .hero-content h1 { font-size: 2.5rem; }
  .trending-card { width: 150px; }
  .trending-poster { width: 150px; height: 210px; }
  .carousel-arrow { display: none; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .features-grid { grid-template-columns: 1fr; }
}

@media (max-width: 480px) {
  .container { padding: 0 var(--space-3); }
  .hero-content { padding: var(--space-5) 0; }
  .faq-question { font-size: 1rem; padding: var(--space-3); }
}

/* ── ANIMATIONS ─────────────────────── */
@keyframes fadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
@keyframes posterFloat { 0%, 100% { transform: translateY(0) rotate(var(--r, 0deg)); } 50% { transform: translateY(-8px) rotate(var(--r, 0deg)); } }

.animate-in { animation: fadeInUp 0.6s ease forwards; opacity: 0; }

.poster-grid { position: absolute; inset: 0; z-index: 0; }
</style>
</head>
